css:
.wrap { max-width: 1360px; margin: 0 auto; }

header {
  position: sticky; top: 0; z-index: 50;
  background: rgba(5,5,5,0.85); backdrop-filter: blur(12px);
  border-bottom: 1px solid var(--border);
  padding: 18px 40px;
}
header .inner { display: flex; justify-content: space-between; align-items: center; gap: 16px; }
.logo { font-family: 'Sora', sans-serif; font-weight: 800; font-size: 20px; letter-spacing: -0.02em; color: #fff; }
.logo span { color: var(--accent); font-weight: 400; }

nav.desktop-nav { display: flex; gap: 8px; font-family: 'JetBrains Mono', monospace; font-size: 12px; letter-spacing: 0.08em; }
nav.desktop-nav a {
  padding: 9px 16px; border-radius: 100px; border: 1px dashed transparent;
  color: #888; transition: all 0.3s ease; white-space: nowrap;
}
nav.desktop-nav a.active { border-color: var(--accent); color: #fff; }

.btn-contato { flex-shrink: 0; }

.menu-toggle {
  display: none; background: none; border: 1px solid var(--border-alt); border-radius: 6px;
  width: 40px; height: 40px; align-items: center; justify-content: center; color: #fff; flex-shrink: 0;
}
.menu-toggle svg { width: 20px; height: 20px; }

.mobile-nav {
  display: none; flex-direction: column; gap: 6px; padding: 16px 0 4px;
  font-family: 'JetBrains Mono', monospace; font-size: 13px; letter-spacing: 0.06em;
}
.mobile-nav a {
  padding: 12px 16px; border-radius: 8px; border: 1px dashed var(--border-alt); color: #999;
}
.mobile-nav a.active { border-color: var(--accent); color: #fff; }

@media (max-width: 860px) {
  header { padding: 16px 20px; }
  nav.desktop-nav { display: none; }
  .btn-contato { display: none; }
  .menu-toggle { display: flex; }
  body.menu-open .mobile-nav { display: flex; }
}

